// import and run Promise polyfill first
import { polyfill as PromisePolyfill } from "es6-promise";
PromisePolyfill();

// Imports and registers
import { HMIWebExperionServicesSuppressionStatus } from "@hw/experionservices/unbundled/HMIWebExperionServicesSuppressionStatus";
import { SuppressionStatusElement } from "@hw/hmiweb-suppression-status/unbundled/index";
import { HmiwebTsLogger } from "@hw/hmiweb-core/js/logging/HmiwebTsLogger";
import { HmiwebTsLocalisation } from "@hw/hmiweb-core/js/localisation/HmiwebTsLocalisation";

let service = new HMIWebExperionServicesSuppressionStatus();
service.register(HmiwebTsLogger.simpleInstance);
const pointName = getURLParam("pointname");
SuppressionStatusElement.register(HmiwebTsLogger.instance, HmiwebTsLocalisation.instance, service.suppressionStatusService, pointName);

window.addEventListener("unload", () => {
    service.dispose();
    service = null;
});

function getURLParam(paramName: string) {
    paramName = paramName.replace(/[\[]/,"\\\[").replace(/[\]]/,"\\\]");
    const regexS = "[\\?&]" + paramName + "=([^&#]*)";
    const regex = new RegExp(regexS, 'i');  // do case insensitive regex search
    const results = regex.exec(window.location.href);
    if (results == null)
        return "";
    else
        return results[1] || "";
}
